import XCTest
import CryptoKit
@testable import AgePonyCore

final class SSHEd25519DiagTests: XCTestCase {
    func test_RecipientFieldsConsistent() throws {
        // Diagnostic against a key generated by hand with ssh-keygen; skipped when absent.
        guard FileManager.default.fileExists(atPath: "/tmp/ref_key.pub") else {
            throw XCTSkip("needs /tmp/ref_key.pub (ssh-keygen -t ed25519 -f /tmp/ref_key)")
        }
        let pubLine = try String(contentsOfFile: "/tmp/ref_key.pub", encoding: .utf8).trimmingCharacters(in: .whitespacesAndNewlines)
        let parsed = try SSHKey.parsePublicKey(pubLine)
        guard case .ed25519(let pub) = parsed.type else {
            return XCTFail("Expected ed25519")
        }
        let recipient = try SSHEd25519Recipient(edPublicKey: pub)
        let hex = { (d: Data) -> String in d.map { String(format: "%02x", $0) }.joined() }
        print("DIAG input edPub:           \(hex(pub))")
        print("DIAG recipient.edPublicKey: \(hex(recipient.edPublicKey))")
        print("DIAG recipient.wireBlob:    \(hex(recipient.wireBlob))")
        print("DIAG recipient.x25519Pub:   \(hex(recipient.x25519Pub))")
        let directConv = try Ed25519Conversion.publicKeyToX25519(edPublicKey: pub)
        print("DIAG direct convertedX:     \(hex(directConv))")
        let directTag = sshEd25519Tag(wireBlob: sshEd25519WireBlob(publicKey: pub))
        print("DIAG direct tag:            \(hex(directTag))")
        let stanza = try recipient.wrap(fileKey: Data(repeating: 0x33, count: 16))
        print("DIAG stanza.args[0] (tag b64): \(stanza.args[0])")
        if let tagBytes = Data(base64Encoded: stanza.args[0] + String(repeating: "=", count: (4 - stanza.args[0].count % 4) % 4)) {
            print("DIAG stanza tag bytes:      \(hex(tagBytes))")
        }
        print("DIAG stanza.args[1] (eph b64): \(stanza.args[1])")
        print("DIAG stanza.body hex:       \(hex(stanza.body))")
    }
}
